  --jenama: oklch(0.55 0.2 250);
  --latar: #ffffff;
}
[data-tema='senja'] {
  --jenama: oklch(0.70 0.18 30);
  --latar: #1a1a2e;
}
body { background: var(--latar); }
.butang { background: var(--jenama); }
```
```html
